import os
import random
from typing import List

ALPHABET_ASCII = (
    b"ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    b"abcdefghijklmnopqrstuvwxyz"
    b"0123456789"
    b"_-+/=,.:\n\r\t !@#$%^&*()[]{}<>?"
)


def _rand_bytes(rng: random.Random, n: int) -> bytes:
    return bytes(rng.getrandbits(8) for _ in range(max(0, n)))


def _pattern_repeating(rng: random.Random, n: int) -> bytes:
    if n <= 0:
        return b""
    seed_len = max(1, min(n, rng.randint(1, 32)))
    seed = _rand_bytes(rng, seed_len)
    return (seed * (n // seed_len + 1))[:n]


def _ascii_bytes(rng: random.Random, n: int) -> bytes:
    if n <= 0:
        return b""
    return bytes(rng.choice(ALPHABET_ASCII) for _ in range(n))


def _biased_zeros(rng: random.Random, n: int) -> bytes:
    if n <= 0:
        return b""
    out = bytearray(n)
    flips = 0 if n == 0 else rng.randint(0, max(1, n // 16))
    for _ in range(flips):
        idx = rng.randrange(n)
        out[idx] = rng.getrandbits(8)
    return bytes(out)


def _counter_block(n: int, start: int) -> bytes:
    if n <= 0:
        return b""
    out = bytearray(n)
    val = start & 0xFF
    for i in range(n):
        out[i] = val
        val = (val + 1) & 0xFF
    return bytes(out)


def _mix_blocks(chunks: List[bytes], n: int) -> bytes:
    if n <= 0:
        return b""
    if not chunks:
        return b"\x00" * n
    out = bytearray()
    i = 0
    while len(out) < n:
        piece = chunks[i % len(chunks)]
        if not piece:
            piece = b"\x00"
        out.extend(piece)
        i += 1
    return bytes(out[:n])


def _safe_range(rng: random.Random, low_incl: int, high_incl: int) -> int:
    """Return a random int in [low_incl, high_incl], clamped safely.
    If high < low, return low.
    """
    if high_incl < low_incl:
        return low_incl
    return rng.randint(low_incl, high_incl)


def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    # Choose a target length for the initial buffer (1..4095)
    bucket = rng.randrange(8)
    if bucket == 0:
        length = rng.randrange(1, 33)
    elif bucket == 1:
        length = rng.randrange(1, 65)
    elif bucket == 2:
        length = rng.randrange(64, 129)
    elif bucket == 3:
        length = rng.randrange(128, 257)
    elif bucket == 4:
        length = rng.randrange(256, 513)
    elif bucket == 5:
        length = rng.randrange(512, 1025)
    else:
        length = rng.randrange(1, 4096)

    # Build component sizes safely relative to total length
    # Ensure positives for small lengths
    half = max(1, length // 2)
    third = max(1, length // 3)
    quarter = max(1, length // 4)

    parts: List[bytes] = []

    # Random entropy segment
    seg1_len = _safe_range(rng, 1, min(256, half))
    parts.append(_rand_bytes(rng, seg1_len))

    # Repeating pattern segment
    seg2_len = _safe_range(rng, 1, min(128, third))
    parts.append(_pattern_repeating(rng, seg2_len))

    # ASCII segment
    seg3_len = _safe_range(rng, 1, min(256, third))
    parts.append(_ascii_bytes(rng, seg3_len))

    # Sparse zeros segment
    seg4_len = _safe_range(rng, 1, min(256, quarter))
    parts.append(_biased_zeros(rng, seg4_len))

    # Counter-like block
    seg5_len = _safe_range(rng, 1, min(128, quarter))
    parts.append(_counter_block(seg5_len, rng.randrange(256)))

    buf = _mix_blocks(parts, length)

    # Occasionally add small headers/trailers if room remains
    mode = rng.randrange(4)
    if mode == 1 and len(buf) + 4 <= 4096:
        le = (len(buf) & 0xFFFFFFFF).to_bytes(4, 'little')
        buf = le + buf
    elif mode == 2 and len(buf) + 10 <= 4096:
        # small trailer; avoid os.urandom (no I/O); use deterministic RNG
        tail_rand = bytes(rng.getrandbits(8) for _ in range(5))
        trailer = b"HDR" + tail_rand + (len(buf) & 0xFFFF).to_bytes(2, 'little')
        buf = buf + trailer

    if len(buf) > 4096:
        buf = buf[:4096]
    if len(buf) == 0:
        buf = b"\x00"

    return buf

import random
import string
from typing import List, Tuple

# Generator for valid/interesting Base64 strings covering libsodium variants
# - Standard (+/), URL-safe (-_), optional padding, optional whitespace
# - Lengths aligned/misaligned to 4, with and without padding
# - Include ignorable whitespace (space, tab, CR, LF) as accepted by stub
# Output is bytes for FUZZ_PARAM_STR to read. The fuzzer stub maps arbitrary
# bytes to an alphabet, but good seeds that are already valid base64-like
# can increase chances of exercising success paths and edge cases.

STD_ALPH = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
URL_ALPH = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_"
PADDING = "="
WS = " \n\r\t"

# Helpers to encode raw bytes to chosen variant Base64 without using external deps.
# We implement a minimal base64 encoder to control padding and alphabet variant.

def _b64_encode_chunk(triple: bytes, alph: str, pad: bool) -> str:
    # triple length 1..3
    b = list(triple) + [0] * (3 - len(triple))
    v = (b[0] << 16) | (b[1] << 8) | b[2]
    c0 = (v >> 18) & 0x3F
    c1 = (v >> 12) & 0x3F
    c2 = (v >> 6) & 0x3F
    c3 = v & 0x3F
    out = [alph[c0], alph[c1]]
    if len(triple) == 1:
        if pad:
            out.append('=')
            out.append('=')
        else:
            # No padding: only first two chars
            pass
    elif len(triple) == 2:
        out.append(alph[c2])
        if pad:
            out.append('=')
        else:
            # No padding: first three chars
            pass
    else:
        out.append(alph[c2])
        out.append(alph[c3])
    return ''.join(out)


def b64_encode(data: bytes, alph: str, pad: bool) -> str:
    out: List[str] = []
    for i in range(0, len(data), 3):
        chunk = data[i:i+3]
        out.append(_b64_encode_chunk(chunk, alph, pad))
    return ''.join(out)


def insert_whitespace(s: str, rng: random.Random) -> str:
    # Insert whitespace at random intervals; libsodium call allows " \n\r\t" to be ignored
    if not s:
        return s
    pieces: List[str] = []
    i = 0
    n = len(s)
    while i < n:
        j = min(n, i + rng.randint(1, 8))
        pieces.append(s[i:j])
        if rng.random() < 0.5:
            # Insert 1-3 whitespace chars
            ws = ''.join(rng.choice(WS) for _ in range(rng.randint(1, 3)))
            pieces.append(ws)
        i = j
    return ''.join(pieces)


def craft_edge_case(rng: random.Random) -> str:
    # Select a scenario to exercise boundary behaviors
    scenario = rng.randrange(10)
    alph = STD_ALPH if rng.random() < 0.5 else URL_ALPH
    pad = rng.random() < 0.6  # more often with padding

    # Sizes targeting 0, 1, 2 mod 3 inputs to vary padding behavior
    if scenario == 0:
        raw = b""  # empty input
    elif scenario == 1:
        raw = rng.randbytes(1)
    elif scenario == 2:
        raw = rng.randbytes(2)
    elif scenario == 3:
        raw = rng.randbytes(3)
    elif scenario == 4:
        raw = rng.randbytes(4)
    elif scenario == 5:
        raw = rng.randbytes(5)
    elif scenario == 6:
        raw = rng.randbytes(30)  # multiple full blocks
    elif scenario == 7:
        raw = rng.randbytes(rng.randint(40, 80))
    elif scenario == 8:
        raw = rng.randbytes(rng.randint(81, 150))
    else:
        raw = rng.randbytes(rng.randint(151, 300))

    s = b64_encode(raw, alph, pad)

    # Optionally remove padding even if pad=True, to mix behaviors
    if rng.random() < 0.3:
        s = s.rstrip('=')

    # Optionally add ignorable whitespace
    if rng.random() < 0.7:
        s = insert_whitespace(s, rng)

    # Occasionally produce lines close to the stub cap (1024 input, bin ~768)
    if rng.random() < 0.15:
        target_len = rng.randint(900, 1024)
        # Extend by appending valid characters
        valid_chars = alph + ('=' if pad else '') + WS
        while len(s) < target_len:
            s += rng.choice(valid_chars)
        s = s[:target_len]

    return s


def craft_strict_valid_block(rng: random.Random) -> str:
    # Produce strictly valid base64 without whitespace and with proper padding
    alph = STD_ALPH if rng.random() < 0.5 else URL_ALPH
    pad = True
    # Choose raw length to vary remainder
    rem = rng.randrange(3)
    base = rng.randint(0, 60) * 3
    raw_len = base + rem
    raw = rng.randbytes(raw_len)
    return b64_encode(raw, alph, pad)


def craft_urlsafe_nopad(rng: random.Random) -> str:
    alph = URL_ALPH
    pad = False
    raw = rng.randbytes(rng.randint(0, 200))
    s = b64_encode(raw, alph, pad)
    # Add some whitespace sometimes (allowed by stub)
    if rng.random() < 0.5:
        s = insert_whitespace(s, rng)
    return s


def craft_padding_edges(rng: random.Random) -> str:
    # Create strings with just padding at end or multiple '=' cases near boundaries
    alph = STD_ALPH if rng.random() < 0.5 else URL_ALPH
    pad = True
    raw = rng.randbytes(rng.randint(1, 16))
    s = b64_encode(raw, alph, pad)
    # Tweak: sometimes keep one '=' only (valid for 2-byte remainder), or full, or none
    if s.endswith('==') and rng.random() < 0.5:
        s = s[:-1]  # single '=' (becomes invalid if original remainder was 1, but many decoders accept strict rules)
    elif s.endswith('=') and rng.random() < 0.3:
        s = s.rstrip('=')
    if rng.random() < 0.5:
        s = insert_whitespace(s, rng)
    return s


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    choice = rng.randrange(6)
    if choice == 0:
        s = craft_edge_case(rng)
    elif choice == 1:
        s = craft_strict_valid_block(rng)
    elif choice == 2:
        s = craft_urlsafe_nopad(rng)
    elif choice == 3:
        s = craft_padding_edges(rng)
    elif choice == 4:
        # Long URL-safe without padding, plenty of data
        s = b64_encode(rng.randbytes(rng.randint(256, 800)), URL_ALPH, False)
        if rng.random() < 0.6:
            s = insert_whitespace(s, rng)
    else:
        # Long standard with padding
        s = b64_encode(rng.randbytes(rng.randint(256, 800)), STD_ALPH, True)
        if rng.random() < 0.6:
            s = insert_whitespace(s, rng)

    # Ensure max length per guidance (<= 4096); stub caps at 1024 anyway
    s = s[:1024]
    return s.encode('ascii', 'strict')
